const KEY='gheaTactico02', OLD='gheaTactico01'; // 0.2.1 mantiene el guardado 0.2
const app=document.querySelector('#app'), $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const eqLabels={weapon:'Arma principal',offhand:'Mano secundaria',helmet:'Casco',armor:'Armadura',boots:'Botas',gloves:'Guantes',ring1:'Anillo 1',ring2:'Anillo 2',amulet:'Amuleto'};
const baseChar=(o={})=>Object.assign({id:crypto.randomUUID?.()||Date.now()+''+Math.random(),name:'Aventurero',sex:'Hombre',height:'Media',hair:'Peinado 1',hairColor:'#4b2e1e',eyeColor:'#4c8a55',clothColor:'#355b86',level:1,xp:0,hp:14,gold:0,dev:0,quest:'none',location:'arca',worldPos:{arca:{x:355,y:270},outskirts:{x:55,y:270},west:{x:650,y:360},jeweler:{x:360,y:430},textile:{x:360,y:430},smith:{x:360,y:430}},startingPoint:'arca',sideQuest:'none',recipes:{collar:false,armor:false},inventory:[],equipment:{weapon:'Espada básica',offhand:null,helmet:null,armor:null,boots:null,gloves:null,ring1:null,ring2:null,amulet:null},tree:{offDamage:0,offLife:0,offIni:0,fury:0,defLife:0,opp:0,guard:0,defIni:0,robust:0}},o);
function fresh(){return {version:2,characters:[],selected:null}}
function migrate(){let s=JSON.parse(localStorage.getItem(KEY)||'null');if(s)return s;let old=JSON.parse(localStorage.getItem(OLD)||'null');if(!old)return fresh();let n=fresh();n.characters=(old.characters||[]).slice(0,3).map(c=>baseChar({...c,quest:old.quest||'none',location:old.location||'arca',gold:c.gold??old.gold??0,tree:{offDamage:c.offDamage||0,offLife:c.offLife||0,offIni:c.offIni||0,fury:c.fury||0,defLife:c.defLife||0,opp:c.opp||0,guard:c.guard||0,defIni:c.defIni||0,robust:c.robust||0}}));n.selected=Math.min(old.selected??0,n.characters.length-1);return n}
let state=migrate();save();function save(){localStorage.setItem(KEY,JSON.stringify(state))}function hero(){return state.characters[state.selected]}
function t(c,k){return c.tree?.[k]||0}function furyBonus(c,hp=c.hp){let r=t(c,'fury');return r>=2&&hp<=4?2:r>=1&&hp<=3?1:0}function maxHp(c){return 14+t(c,'offLife')*2+t(c,'defLife')*2+t(c,'robust')*5+(c.equipment.boots==='Botas de tela'?2:0)+(c.equipment.armor==='Armadura de cuero de jabalí'?3:0)}function initiative(c){return 4+t(c,'offIni')+t(c,'defIni')}function weaponBonus(name){return name==='Espada básica'||name==='Daga oxidada'?1:0}function baseDamage(c,hp=c.hp){return 1+t(c,'offDamage')+weaponBonus(c.equipment.weapon)+weaponBonus(c.equipment.offhand)+furyBonus(c,hp)}
function toast(s){document.body.insertAdjacentHTML('beforeend',`<div class="toast">${s}</div>`);setTimeout(()=>$('.toast')?.remove(),1700)}
function modal(html,closable=true){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="card">${html}${closable?'<div class="actions"><button class="secondary" onclick="closeModal()">Cerrar</button></div>':''}</div></div>`)}window.closeModal=()=>$('#modal')?.remove();
function home(){app.innerHTML=`<section class="screen center"><div><h1>⚔️ GHEA TÁCTICO</h1><p class="sub">Prototipo 0.2.7.3</p><button id="play">Jugar</button><p class="small">Guardado local · ${state.characters.length}/3 Aventureros</p></div></section>`;$('#play').onclick=characters}
function characters(){app.innerHTML=`<section class="screen"><h2>Aventureros</h2><div id="chars"></div><div class="actions"><button id="new" ${state.characters.length>=3?'disabled':''}>${state.characters.length>=3?'Límite 3/3':'Crear Aventurero'}</button><button class="secondary" id="back">Volver</button></div></section>`;let box=$('#chars');if(!state.characters.length)box.innerHTML='<div class="card">Todavía no creaste ningún Aventurero.</div>';state.characters.forEach((c,i)=>box.insertAdjacentHTML('beforeend',`<div class="card char-card"><div><b>${esc(c.name)}</b> · Humano Guerrero · Nivel ${c.level}<br><span class="small">❤️ ${c.hp}/${maxHp(c)} · ⚡ Ini ${initiative(c)} · PA 4 · PM 3 · 🪙 ${c.gold}</span></div><div class="char-buttons"><button onclick="enter(${i})">Seleccionar</button><button class="danger" onclick="askDelete(${i})">Eliminar</button></div></div>`));$('#new').onclick=createChar;$('#back').onclick=home}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
window.enter=i=>{state.selected=i;save();world()};window.askDelete=i=>{let c=state.characters[i];modal(`<h3>¿Eliminar a ${esc(c.name)}?</h3><p>Se eliminará este personaje y todo su progreso. Esta acción no se puede deshacer.</p><div class="actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="danger" id="confirmDelete">Eliminar definitivamente</button></div>`,false);$('#confirmDelete').onclick=()=>{state.characters.splice(i,1);if(state.selected===i)state.selected=null;else if(state.selected>i)state.selected--;save();closeModal();characters()}}
function createChar(){if(state.characters.length>=3)return;app.innerHTML=`<section class="screen"><h2>Crear Aventurero</h2><div class="card grid2"><label>Nombre<input id="name" maxlength="16" value="Aventurero"></label><label>Sexo<select id="sex"><option>Hombre</option><option>Mujer</option></select></label><label>Raza<select><option>Humano</option><option disabled>Enano — próximamente</option><option disabled>Elfo — próximamente</option></select></label><label>Clase<select><option>Guerrero</option><option disabled>Más clases — próximamente</option></select></label><label>Altura<select id="height"><option>Baja</option><option selected>Media</option><option>Alta</option></select></label><label>Peinado<select id="hair"><option>Peinado 1</option><option>Peinado 2</option></select></label><label>Color de pelo<input id="hairColor" type="color" value="#4b2e1e"></label><label>Color de ojos<input id="eyeColor" type="color" value="#4c8a55"></label><label>Color de ropa<input id="clothColor" type="color" value="#355b86"></label></div><div class="actions"><button id="make">Crear</button><button class="secondary" id="cancel">Cancelar</button></div></section>`;$('#make').onclick=()=>{let c=baseChar({name:$('#name').value.trim()||'Aventurero',sex:$('#sex').value,height:$('#height').value,hair:$('#hair').value,hairColor:$('#hairColor').value,eyeColor:$('#eyeColor').value,clothColor:$('#clothColor').value});state.characters.push(c);save();characters()};$('#cancel').onclick=characters}
const mapData={
arca:{w:720,h:540,obstacles:[{x:250,y:25,w:250,h:120},{x:20,y:55,w:90,h:80},{x:570,y:55,w:110,h:95},{x:80,y:420,w:120,h:80},{x:500,y:430,w:130,h:70}],mage:{x:350,y:195},smith:{x:165,y:180},jeweler:{x:485,y:180},textile:{x:485,y:350},itemshop:{x:165,y:350},east:{x:685,y:376},west:{x:25,y:300}},
outskirts:{w:720,h:540,obstacles:[{x:180,y:70,w:90,h:70},{x:390,y:80,w:75,h:120},{x:260,y:350,w:120,h:70},{x:545,y:320,w:80,h:95}],enemy:{x:560,y:190},exit:{x:25,y:270}},
west:{w:720,h:540,obstacles:[{x:160,y:80,w:80,h:90},{x:330,y:320,w:95,h:80},{x:520,y:70,w:80,h:110}],guard:{x:555,y:185},exit:{x:695,y:270},boars:[{x:220,y:220},{x:410,y:390}]},
smith:{w:720,h:540,obstacles:[],npc:{x:360,y:180},exit:{x:360,y:505}},jeweler:{w:720,h:540,obstacles:[],npc:{x:360,y:180},exit:{x:360,y:505}},textile:{w:720,h:540,obstacles:[],npc:{x:360,y:180},exit:{x:360,y:505}},itemshop:{w:720,h:540,obstacles:[],npc:{x:360,y:180},exit:{x:360,y:505}}
};
let moving=null,patrolTimer=null;
function side(c){return c.sideQuest||'none'}
function countItem(c,n){return c.inventory.filter(x=>x===n).length}
function removeItems(c,n,q){for(let i=0;i<q;i++){let k=c.inventory.indexOf(n);if(k<0)return false;c.inventory.splice(k,1)}return true}
function missionArrow(c,map,pos,d){let target=null,label='';if(c.quest==='accepted'){if(map==='arca'){target=d.east;label='Salida hacia Afueras'}else if(map==='outskirts'){target=d.enemy;label='Grupo enemigo'}}else if(c.quest==='done'){if(map==='outskirts'){target={x:8,y:376};label='Regresá a Arca'}else if(map==='arca'){target=d.mage;label='Maestro de Arca'}}else if(c.quest==='none'&&map==='arca'){target=d.mage;label='Misión disponible'}if(map==='arca'&&side(c)==='deliverShield'){target=d.west;label='Puerta Oeste'}if(map==='west'&&['deliverShield','hunt','huntReady','returnCollar','returnArmor'].includes(side(c))){target=d.guard;label='Guardia Oeste'}if(map==='arca'&&side(c)==='craftCollar'){target=d.jeweler;label='Joyero'}if(map==='arca'&&side(c)==='craftArmor'){target=d.textile;label='Tienda textil'}if(!target)return'';let ang=Math.atan2(target.y-pos.y,target.x-pos.x)*180/Math.PI;return `<div class="mission-arrow" title="${label}"><span style="transform:rotate(${ang}deg)">➜</span><small>${label}</small></div>`}
function world(){clearInterval(patrolTimer);let c=hero();if(!c)return characters();if(!c.worldPos.west)c.worldPos.west={x:650,y:360};if(!c.worldPos.smith)c.worldPos.smith={x:360,y:430};if(!c.worldPos.jeweler)c.worldPos.jeweler={x:360,y:430};if(!c.worldPos.textile)c.worldPos.textile={x:360,y:430};if(!c.worldPos.itemshop)c.worldPos.itemshop={x:360,y:430};let map=c.location||'arca',d=mapData[map]||mapData.arca,pos=c.worldPos[map]||{x:50,y:270},title={arca:'Arca',outskirts:'Afueras de Arca',west:'Camino de la Puerta Oeste',smith:'Herrería',jeweler:'Joyería',textile:'Tienda de telas y cuero',itemshop:'Tienda de artículos'}[map];let scenery=d.obstacles.map((o,i)=>`<div class="${i%2?'tree':'wall'}" style="left:${o.x}px;top:${o.y}px;width:${o.w}px;height:${o.h}px"></div>`).join('');let actors='';if(map==='arca'){actors=`<div class="actor npc-world" id="mage" style="left:${d.mage.x}px;top:${d.mage.y}px">🧙</div>${c.quest==='none'?`<div class="marker" style="left:${d.mage.x}px;top:${d.mage.y-18}px">!</div>`:''}${c.quest==='done'?`<div class="marker" style="left:${d.mage.x}px;top:${d.mage.y-18}px">?</div>`:''}<div class="building smith-building" id="smithDoor" style="left:${d.smith.x}px;top:${d.smith.y}px">⚒️<small>Herrería</small></div><div class="building" id="jewelerDoor" style="left:${d.jeweler.x}px;top:${d.jeweler.y}px">💎<small>Joyero</small></div><div class="building" id="textileDoor" style="left:${d.textile.x}px;top:${d.textile.y}px">🧵<small>Textil</small></div><div class="building" id="itemShopDoor" style="left:${d.itemshop.x}px;top:${d.itemshop.y}px">🧪<small>Artículos</small></div><div class="exit">AFUERAS →</div><div class="exit west-exit">← PUERTA OESTE</div>`}else if(map==='outskirts'){actors=`${c.quest==='accepted'?`<div class="actor enemy-world" id="enemy" style="left:${d.enemy.x}px;top:${d.enemy.y}px">🗡️</div><div class="hint" style="left:${d.enemy.x}px;top:${d.enemy.y}px">Grupo de bandidos</div>`:''}<div class="exit" style="left:8px;right:auto">← ARCA</div>`}else if(map==='west'){actors=`<div class="actor npc-world" id="guard" style="left:${d.guard.x}px;top:${d.guard.y}px">🛡️</div><div class="marker" style="left:${d.guard.x}px;top:${d.guard.y-18}px">${['deliverShield','huntReady','returnCollar','returnArmor'].includes(side(c))?'?':side(c)==='hunt'?'!':''}</div><div class="actor enemy-world boar-patrol" id="boar0" style="left:${d.boars[0].x}px;top:${d.boars[0].y}px">🐗</div><div class="actor enemy-world boar-patrol" id="boar1" style="left:${d.boars[1].x}px;top:${d.boars[1].y}px">🐗</div><div class="exit west-return">ARCA →</div>`}else{actors=`<div class="actor npc-world artisan" id="artisan" style="left:${d.npc.x}px;top:${d.npc.y}px">${map==='smith'?'⚒️':map==='jeweler'?'💎':map==='textile'?'🧵':'🧪'}</div><div class="exit interior-exit">SALIR</div>`}
app.innerHTML=`<section class="screen"><div class="topbar"><b>${esc(c.name)} · Nv.${c.level}</b><span>❤️ ${c.hp}/${maxHp(c)} · ✨ ${c.xp}/${xpNeed(c.level)} · 🪙 ${c.gold}</span></div><h3 class="map-title">${title}</h3>${questTracker(c)}<div class="world-wrap"><div class="world ${['smith','jeweler','textile','itemshop'].includes(map)?'interior':''}" id="worldMap">${map==='arca'?'<div class="academy"></div><div class="road main"></div><div class="road vert"></div>':map==='outskirts'||map==='west'?'<div class="road main" style="top:235px"></div>':'<div class="shop-floor"></div>'}${scenery}${actors}<div class="actor hero-world" id="worldHero" style="left:${pos.x}px;top:${pos.y}px">⚔️</div>${missionArrow(c,map,pos,d)}</div></div><p class="small">Tocá un lugar del escenario para moverte.</p><div class="actions"><button id="inv">Inventario</button><button id="tree">Desarrollo</button><button id="rest">Descansar</button><button class="secondary" id="menu">Personajes</button></div><div class="test-panel"><b>🧪 PRUEBAS</b><button id="testLevel">⬆ Subir nivel</button><button id="testRest">❤ Descanso instantáneo</button></div></section>`;
$('#worldMap').onclick=e=>worldTap(e,map);$('#mage')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.mage,questDialog)});$('#enemy')?.addEventListener('click',e=>{e.stopPropagation();if(c.quest==='accepted')approachAndInteract(map,d.enemy,enemyGroup)});$('#guard')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.guard,guardDialog)});$('#smithDoor')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.smith,()=>enterInterior('smith'),72)});$('#jewelerDoor')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.jeweler,()=>enterInterior('jeweler'),72)});$('#textileDoor')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.textile,()=>enterInterior('textile'),72)});$('#itemShopDoor')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.itemshop,()=>enterInterior('itemshop'),72)});$('#artisan')?.addEventListener('click',e=>{e.stopPropagation();approachAndInteract(map,d.npc,()=>artisanDialog(map))});document.querySelectorAll('.boar-patrol').forEach((b,i)=>b.onclick=e=>{e.stopPropagation();let r=b.getBoundingClientRect(),wr=$('#worldMap').getBoundingClientRect(),target={x:(r.left+r.width/2-wr.left)*720/wr.width,y:(r.top+r.height/2-wr.top)*540/wr.height};approachAndInteract(map,target,()=>boarGroup(i))});$('#inv').onclick=inventory;$('#tree').onclick=treeMenu;$('#menu').onclick=characters;$('#rest').onclick=()=>rest(c);$('#testLevel').onclick=()=>testLevelUp(c);$('#testRest').onclick=()=>testInstantRest(c);if(map==='west')startBoarPatrol()}
function questTracker(c){let main=c.quest==='accepted'?'Principal: derrotá al grupo de bandidos en las Afueras.':c.quest==='done'?'Principal: regresá con el Maestro.':c.quest==='none'?'Principal disponible: hablá con el Maestro.':'Sin misión principal.';let sq={none:'Secundaria: hablá con el Herrero de Arca.',deliverShield:'Secundaria: entregá el escudo al Guardia de la Puerta Oeste.',hunt:'Secundaria: conseguí 5 Pieles y 3 Colmillos de jabalí.',huntReady:'Secundaria: volvé con el Guardia Oeste.',craftCollar:'Secundaria: fabricá el Collar de Jabalí con el Joyero.',returnCollar:'Secundaria: llevá el Collar de Jabalí al Guardia.',craftArmor:'Secundaria: fabricá la Armadura de Cuero de Jabalí en Textil.',returnArmor:'Secundaria: llevá la Armadura al Guardia.',complete:'Cadena del Guardia Oeste completada.'}[side(c)];return `<div class="quest-track">📜 ${main}<br>🧭 ${sq}</div>`}
function enterInterior(where){let c=hero();c.location=where;c.worldPos[where]={x:360,y:430};save();world()}
function artisanDialog(map){if(map==='smith')smithDialog();else if(map==='jeweler')jewelerDialog();else if(map==='textile')textileDialog();else itemShopDialog()}
function smithDialog(){let c=hero(),q=side(c),mission=q==='none'?'<button id="smithQuest">Encargo: llevar un escudo</button>':'';modal(`<h3>⚒️ Herrero de Arca</h3><p>Trabajo el metal para los guardias y Aventureros de Arca.</p>${mission}<button id="sellHere">Vender objetos</button>`);$('#smithQuest')?.addEventListener('click',()=>{if(c.inventory.length>=12)return toast('Necesitás espacio en la mochila.');c.inventory.push('Escudo del Guardia');c.sideQuest='deliverShield';save();closeModal();toast('Recibiste el Escudo del Guardia.');world()});$('#sellHere').onclick=()=>sellMenu('Herrero')}
function guardDialog(){let c=hero(),q=side(c);if(q==='deliverShield'){if(countItem(c,'Escudo del Guardia')){removeItems(c,'Escudo del Guardia',1);c.gold+=5;c.sideQuest='hunt';save();modal(`<h3>🛡️ Guardia Oeste</h3><p>Gracias por traer el escudo. Tomá <b>5 oro</b>.</p><p>Necesito materiales de los jabalíes de esta zona: <b>5 Pieles y 3 Colmillos</b>.</p><button id="okg">Aceptar encargo</button>`,false);$('#okg').onclick=()=>{closeModal();world()};return}}if(q==='hunt'||q==='huntReady'){let hides=countItem(c,'Piel de jabalí'),tusks=countItem(c,'Colmillo de jabalí');if(hides>=5&&tusks>=3){c.sideQuest='craftCollar';save();modal(`<h3>🛡️ Guardia Oeste</h3><p>Perfecto, ya tenés los materiales. Conserválos: los artesanos los van a necesitar.</p><p>Primero andá con el <b>Joyero de Arca</b> y encargale un Collar de Jabalí.</p><p class="small">La recompensa de esta etapa queda pendiente de definir.</p>`);return}modal(`<h3>🛡️ Guardia Oeste</h3><p>Necesito <b>5 Pieles</b> y <b>3 Colmillos</b>.</p><p>Tenés: ${hides}/5 Pieles · ${tusks}/3 Colmillos.</p>`);return}if(q==='returnCollar'){if(countItem(c,'Collar de Jabalí')){removeItems(c,'Collar de Jabalí',1);c.gold+=20;c.sideQuest='craftArmor';save();modal(`<h3>🛡️ Guardia Oeste</h3><p>Excelente. Me quedo con el collar.</p><p>Recibís <b>20 oro</b>: 15 por el collar + 5 por las molestias.</p><p>Ahora llevá las 5 Pieles al comerciante de telas y cuero para fabricar una armadura.</p>`);return}}if(q==='returnArmor'){if(countItem(c,'Armadura de cuero de jabalí')){removeItems(c,'Armadura de cuero de jabalí',1);c.gold+=15;c.sideQuest='complete';c.recipes={...(c.recipes||{}),collar:true,armor:true};save();modal(`<h3>🛡️ Guardia Oeste</h3><p>Trabajo terminado. Me quedo con la armadura.</p><p>Recibís <b>15 oro</b>: 10 por la armadura + 5 por las molestias.</p><p>Las recetas de Jabalí quedan disponibles para que fabriques tus propias copias.</p>`);return}}modal(`<h3>🛡️ Guardia Oeste</h3><p>${q==='complete'?'Gracias otra vez. Los jabalíes siguen siendo peligrosos por este camino.':'Mantené los ojos abiertos en el camino.'}</p>`)}
function jewelerDialog(){let c=hero(),canMission=side(c)==='craftCollar',unlocked=c.recipes?.collar||side(c)==='complete',craft=(canMission||unlocked)?`<button id="craftCollar">Fabricar Collar de Jabalí · 3 Colmillos + 🪙3</button>`:'<p class="small">Todavía no conocés ninguna receta de joyería.</p>';modal(`<h3>💎 Joyero de Arca</h3><p>Anillos y collares. Por ahora no tengo artículos a la venta.</p>${craft}<button id="sellHere">Vender objetos</button>`);$('#craftCollar')?.addEventListener('click',()=>craftItem('Collar de Jabalí','Colmillo de jabalí',3,3,'returnCollar'));$('#sellHere').onclick=()=>sellMenu('Joyero')}
function textileDialog(){let c=hero(),canMission=side(c)==='craftArmor',unlocked=c.recipes?.armor||side(c)==='complete',craft=(canMission||unlocked)?`<button id="craftArmor">Fabricar Armadura de Cuero de Jabalí · 5 Pieles + 🪙3</button>`:'<p class="small">Todavía no conocés ninguna receta de cuero.</p>';modal(`<h3>🧵 Telas y Cuero</h3><p>Botas, guantes, capuchas y armaduras. Por ahora no tengo artículos a la venta.</p>${craft}<button id="sellHere">Vender objetos</button>`);$('#craftArmor')?.addEventListener('click',()=>craftItem('Armadura de cuero de jabalí','Piel de jabalí',5,3,'returnArmor'));$('#sellHere').onclick=()=>sellMenu('Textil')}
function craftItem(result,mat,qty,cost,next){let c=hero();if(c.inventory.length>=12&&countItem(c,mat)<qty)return toast('Necesitás espacio en la mochila.');if(countItem(c,mat)<qty)return toast(`Faltan materiales: ${qty} × ${mat}.`);if(c.gold<cost)return toast(`Necesitás ${cost} de oro.`);removeItems(c,mat,qty);c.gold-=cost;addItem(c,result);if(side(c)==='craftCollar'&&result==='Collar de Jabalí')c.sideQuest='returnCollar';if(side(c)==='craftArmor'&&result==='Armadura de cuero de jabalí')c.sideQuest='returnArmor';save();closeModal();toast(`${result} fabricado.`);world()}
function itemShopDialog(){modal(`<h3>🧪 Tienda de artículos</h3><p>Consumibles básicos para Aventureros.</p><button id="buyHere">Comprar</button><button id="sellHere">Vender objetos</button>`);$('#buyHere').onclick=()=>buyMenu();$('#sellHere').onclick=()=>sellMenu('Tienda de artículos')}
function buyMenu(){closeModal();let c=hero(),stock=[['Poción de Vida Básica',3],['Antídoto',2],['Vendas',2]],rows=stock.map(([n,p])=>`<button class="sell-row" data-buy="${esc(n)}" data-price="${p}">${esc(n)} <b>🪙${p}</b></button>`).join('');modal(`<h3>Comprar · Artículos</h3><p>🪙 Oro: <b id="shopGold">${c.gold}</b> · Mochila: <b id="shopBag">${c.inventory.length}/12</b></p>${rows}<p class="small">Podés comprar varios artículos sin salir de la tienda.</p>`,true);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let n=b.dataset.buy,p=+b.dataset.price;if(c.gold<p)return toast('No tenés suficiente oro.');if(c.inventory.length>=12)return toast('La mochila está llena.');c.gold-=p;c.inventory.push(n);save();$('#shopGold').textContent=c.gold;$('#shopBag').textContent=c.inventory.length+'/12';toast(`${n} comprado.`)})}
function sellMenu(place){closeModal();let c=hero(),selected=new Set();function draw(){let rows=c.inventory.map((n,i)=>{let d=itemData[n]||{sell:0};return d.sell?`<button class="sell-row ${selected.has(i)?'selected-sale':''}" data-sell="${i}">${selected.has(i)?'☑️':'⬜'} ${esc(n)} <b>+🪙${d.sell}</b></button>`:''}).join('');let total=[...selected].reduce((a,i)=>a+(itemData[c.inventory[i]]?.sell||0),0);let m=$('#modal .card');m.innerHTML=`<h3>Vender · ${place}</h3><p>🪙 Oro: <b>${c.gold}</b></p>${rows||'<p>No tenés objetos vendibles.</p>'}<p><b>${selected.size}</b> seleccionados · recibirás <b>🪙${total}</b></p><div class="actions"><button id="sellSelected" ${selected.size?'':'disabled'}>Vender seleccionados</button><button class="secondary" id="closeSell">Volver</button></div><p class="small">Los objetos de misión no se pueden vender.</p>`;document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{let i=+b.dataset.sell;selected.has(i)?selected.delete(i):selected.add(i);draw()});$('#closeSell').onclick=closeModal;$('#sellSelected').onclick=()=>{let idx=[...selected].sort((a,b)=>b-a),total=0,names=[];for(let i of idx){let n=c.inventory[i],v=itemData[n]?.sell||0;if(v){total+=v;names.push(n);c.inventory.splice(i,1)}}c.gold+=total;selected.clear();save();toast(`${names.length} objeto${names.length!==1?'s':''} vendidos por ${total} oro.`);draw()}}modal('<div></div>',false);draw()}
function useConsumable(i,name,use){let c=hero();if(use==='heal'){if(c.hp>=maxHp(c))return toast('Ya tenés la Vida completa.');c.hp=Math.min(maxHp(c),c.hp+3)}else if(use==='antidote'){toast('El Antídoto se podrá usar durante combate cuando haya Veneno.');return}else if(use==='bandage'){toast('Las Vendas se podrán usar durante combate cuando haya Herida.');return}c.inventory.splice(i,1);save();closeModal();inventory();toast(`${name} utilizado.`)}
function boarGroup(i){modal(`<h3>Manada de jabalíes</h3><p>🐗 Jabalí ×3</p><p class="small">Este grupo patrulla el Camino de la Puerta Oeste.</p><div class="actions"><button id="fightBoars">Combatir</button><button class="secondary" onclick="closeModal()">Cancelar</button></div>`,false);$('#fightBoars').onclick=()=>{closeModal();battleStart('boars')}}
function startBoarPatrol(){let phase=0;patrolTimer=setInterval(()=>{if(hero()?.location!=='west')return clearInterval(patrolTimer);phase++;document.querySelectorAll('.boar-patrol').forEach((el,i)=>{let base=mapData.west.boars[i],dx=((phase+i)%8<4?1:-1)*18,dy=i?Math.sin(phase)*12:Math.cos(phase)*12;el.style.left=(base.x+dx)+'px';el.style.top=(base.y+dy)+'px'})},700)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function blocked(map,x,y){let d=mapData[map],r=24;return x<r||y<r||x>d.w-r||y>d.h-r||d.obstacles.some(o=>x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)}
function worldTap(e,map){let r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)*720/r.width,y=(e.clientY-r.top)*540/r.height;moveWorld(map,{x,y})}
function pathfind(map,start,goal){const step=24,cols=30,rows=23,s={x:clamp(Math.floor(start.x/step),0,cols-1),y:clamp(Math.floor(start.y/step),0,rows-1)},g={x:clamp(Math.floor(goal.x/step),0,cols-1),y:clamp(Math.floor(goal.y/step),0,rows-1)},key=p=>p.x+','+p.y,q=[s],came=new Map([[key(s),null]]);while(q.length){let a=q.shift();if(a.x===g.x&&a.y===g.y)break;for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let n={x:a.x+dx,y:a.y+dy},k=key(n),px=n.x*step+12,py=n.y*step+12;if(n.x<0||n.y<0||n.x>=cols||n.y>=rows||came.has(k)||blocked(map,px,py))continue;came.set(k,a);q.push(n)}}if(!came.has(key(g)))return[];let cur=g,out=[];while(cur){out.push({x:cur.x*step+12,y:cur.y*step+12});cur=came.get(key(cur))}return out.reverse()}
function moveWorld(map,goal,done){let c=hero(),p=c.worldPos[map],path=pathfind(map,p,goal);if(path.length<2){done?.();return}clearInterval(moving);let i=1;moving=setInterval(()=>{if(i>=path.length){clearInterval(moving);moving=null;save();checkTransition(map);done?.();return}let n=path[i++];c.worldPos[map]=n;let el=$('#worldHero');if(el){el.style.left=n.x+'px';el.style.top=n.y+'px'}},90)}
function approachAndInteract(map,target,done,range=62){let c=hero(),p=c.worldPos[map];if(dist(p,target)<=range){done();return}let candidates=[[range,0],[-range,0],[0,range],[0,-range],[range*.7,range*.7],[-range*.7,range*.7],[range*.7,-range*.7],[-range*.7,-range*.7]].map(([dx,dy])=>({x:target.x+dx,y:target.y+dy})).filter(q=>!blocked(map,q.x,q.y));let best=null,bestPath=null;for(let q of candidates){let path=pathfind(map,p,q);if(path.length>1&&(!bestPath||path.length<bestPath.length)){best=q;bestPath=path}}if(!best){toast('No hay un camino libre hasta ese objetivo.');return}moveWorld(map,best,()=>{if(hero()?.location===map&&dist(hero().worldPos[map],target)<=range+28)done()})}
function checkTransition(map){let c=hero(),p=c.worldPos[map],d=mapData[map];if(map==='arca'){if(dist(p,d.east)<70){c.location='outskirts';c.worldPos.outskirts={x:55,y:270};save();return world()}if(dist(p,d.west)<70){c.location='west';c.worldPos.west={x:650,y:360};save();return world()}}else if(map==='outskirts'&&dist(p,d.exit)<70){c.location='arca';c.worldPos.arca={x:650,y:376};save();world()}else if(map==='west'&&dist(p,d.exit)<70){c.location='arca';c.worldPos.arca={x:60,y:300};save();world()}else if(['smith','jeweler','textile','itemshop'].includes(map)&&dist(p,d.exit)<75){c.location='arca';c.worldPos.arca={x:map==='smith'?165:map==='jeweler'?485:map==='textile'?485:165,y:map==='smith'||map==='jeweler'?220:390};save();world()}}
function questDialog(){let c=hero(),text,btn='';if(c.quest==='none'){text='Se ha detectado un grupo de bandidos en las afueras de Arca. Encárgate de ellos y regresa.';btn='<button id="accept">Aceptar misión</button>'}else if(c.quest==='accepted'){text='Sal de Arca. El grupo se encuentra en las afueras.'}else if(c.quest==='done'){text='Buen trabajo. Has cumplido tu misión.';btn='<button id="turnin">Entregar misión (+4 EXP, +5 oro)</button>'}else text='Continúa con tu entrenamiento, Aventurero.';modal(`<h3>Maestro de Arca</h3><p>${text}</p>${btn}`);$('#accept')?.addEventListener('click',()=>{c.quest='accepted';save();closeModal();world()});$('#turnin')?.addEventListener('click',()=>{c.xp+=4;c.gold+=5;c.quest='none';levelCheck(c);save();closeModal();toast('Misión entregada. El Maestro vuelve a tenerla disponible.');world()})}
function enemyGroup(){modal(`<h3>Grupo enemigo</h3><p>🐗 <b>Jabalí</b> · Vida 10<br>🗡️ <b>Bandido con Daga</b> · Vida 8<br>🏹 <b>Bandido con Ballesta</b> · Vida 8</p><p class="small">Entrar al combate iniciará el encuentro táctico.</p><div class="actions"><button id="fight">Combatir</button><button class="secondary" onclick="closeModal()">Cancelar</button></div>`,false);$('#fight').onclick=()=>{closeModal();battleStart()}}
let B=null,battleAnimating=false;const obs=new Set(['3,3','3,4','6,5','6,6','7,6']);
