function battleStart(encounter='bandits'){let c=hero();B={encounter,round:1,turn:0,selectedAction:'move',bodyTarget:null,carryingBody:null,timer:30,timerId:null,log:[],deployment:true,deployPos:null,deployTiles:['0,3','1,3','0,4','2,5','1,6','2,6','0,8','2,8'],units:encounter==='boars'?[unit('hero',c.name,'⚔️',-1,-1,c.hp,initiative(c),4,3,'hero'),unit('boar1','Jabalí','🐗',7,2,10,3,3,3,'boar'),unit('boar2','Jabalí','🐗',8,5,10,3,3,3,'boar'),unit('boar3','Jabalí','🐗',7,8,10,3,3,3,'boar')]:[unit('hero',c.name,'⚔️',-1,-1,c.hp,initiative(c),4,3,'hero'),unit('boar','Jabalí','🐗',8,8,10,3,3,3,'boar'),unit('dagger','Bandido con Daga','🗡️',4,5,8,3,3,3,'dagger'),unit('cross','Bandido con Ballesta','🏹',7,3,8,2,3,3,'cross')]};let battleHero=B.units.find(u=>u.id==='hero');battleHero.max=maxHp(c);battleHero.hp=Math.min(c.hp,battleHero.max);let foes=B.units.filter(u=>u.type!=='hero').sort((a,b)=>b.ini-a.ini||Math.random()-.5);B.order=['hero',...foes.map(u=>u.id)];renderDeployment()}
function renderDeployment(){let tiles='';for(let y=0;y<10;y++)for(let x=0;x<10;x++){let k=`${x},${y}`,z=occupied(x,y),valid=B.deployTiles.includes(k)&&!obs.has(k)&&!z,chosen=B.deployPos===k,classes=['tile'];if(obs.has(k))classes.push('obstacle');if(valid)classes.push('deploy');if(chosen)classes.push('deploy-chosen');tiles+=`<div class="${classes.join(' ')}" data-x="${x}" data-y="${y}">${z?`<div class="unit-piece"><div class="unit-hp"><i style="width:${Math.max(0,Math.min(100,z.hp/z.max*100))}%"></i></div><span class="unit-icon">${z.icon}</span><span class="unit-badge">${z.hp}</span></div>`:chosen?'<div class="deploy-hero">⚔️</div>':''}</div>`}app.innerHTML=`<section class="screen"><div class="topbar"><b>Despliegue inicial</b><span>Antes de la Ronda 1</span></div><div class="card"><b>Elegí dónde iniciar</b><p class="small">Tocá una de las posiciones resaltadas. Algunas están juntas y otras separadas. La iniciativa y el temporizador comenzarán recién cuando confirmes.</p></div><div class="battle-grid" id="battleGrid">${tiles}</div><div class="actions deployment-actions"><button id="confirmDeploy" ${B.deployPos?'':'disabled'}>Confirmar posición</button><button class="secondary" id="cancelBattle">Cancelar combate</button></div></section>`;$('#battleGrid').onclick=e=>{let t=e.target.closest('.tile');if(!t)return;let k=`${t.dataset.x},${t.dataset.y}`;if(!B.deployTiles.includes(k)||obs.has(k)||occupied(+t.dataset.x,+t.dataset.y))return;B.deployPos=k;renderDeployment()};$('#confirmDeploy').onclick=()=>{let [x,y]=B.deployPos.split(',').map(Number),h=getU('hero');h.x=x;h.y=y;B.deployment=false;B.deployPos=null;beginTurn()};$('#cancelBattle').onclick=()=>{B=null;world()}}
function cur(){return B.units.find(u=>u.id===B.order[B.turn])}function getU(id){return B.units.find(u=>u.id===id)}function occupied(x,y){return B.units.find(u=>u.x===x&&u.y===y)}function aliveOccupied(x,y){return B.units.find(u=>u.alive&&u.x===x&&u.y===y)}function corpseAt(x,y){return B.units.find(u=>!u.alive&&u.x===x&&u.y===y)}function free(x,y){return x>=0&&y>=0&&x<10&&y<10&&!obs.has(`${x},${y}`)&&!occupied(x,y)}function md(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}function adj8(a,b){return Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y))===1}
